fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    
    // Handle edge cases: empty or single element
    if n <= 1 {
        return numbers;
    }
    
    // For n ≥ 2, result will have 2*n - 1 elements
    let mut result = Vec::with_capacity(2 * n - 1);
    
    // Iterate through all but the last element
    for i in 0..(n - 1) {
        result.push(numbers[i]);
        result.push(delimiter);
    }
    
    // Add the last element without delimiter
    result.push(numbers[n - 1]);
    
    result
}